//! GFN1-xTB parameters for H to Rn (every element of GFN1-xTB).
//!
//! Source: xtb 6.7.1 (grimme-lab/xtb, LGPL-3.0-or-later): the element table `ELEMENTS`
//! is generated by `tools/params/gen_gfn1_xtb.py` from `src/xtb/gfn1.f90` (shells, Slater
//! exponents, self energies, shell polynomials, hardnesses, third-order and repulsion
//! parameters, halogen-bond strengths, the kinds that shift their self energies with the
//! coordination number) and `src/param/` (Pauling electronegativities `paulingen.f90`,
//! atomic radii `atomicrad.f90`, D3 covalent radii `covalentradd3.f90`), and checked there
//! value by value against the parameters tblite exports; the global constants below are
//! those of `gfn1.f90` (`third_party/DISPERSION_AND_PARAMETERS.md`, "GFN1-xTB"). Where
//! tblite 0.4.0 (the reference of the tests) differs from xtb, tblite is followed: Stewart's
//! STO-6G 4s and 4p expansions (xtb keeps older values),
//! the cutoffs of the coordination number (25 Bohr) and of the dispersion (50 Bohr), and its
//! constants (Bohr radius 0.52917721090380 Angstrom, Boltzmann constant
//! 3.166808578545117e-6 Hartree/K).
//!
//! MultiOptPy: no counterpart (new in mopt-rs; MultiOptPy calls tblite for GFN1-xTB).
//!
//! This file is part of mopt-rs.
//! Copyright (C) 2023-2026 ss0832
//! SPDX-License-Identifier: GPL-3.0-or-later

pub use super::elements::ELEMENTS;
use crate::domain::Element;
use crate::error::{MoptError, MoptResult};

/// Angstrom per Bohr as tblite converts the parameters (CODATA 2018).
pub const BOHR_ANGSTROM: f64 = 0.529_177_210_903_80;
/// eV per Hartree as xtb and tblite convert the self energies.
pub const HARTREE_EV: f64 = 27.211_385_05;
/// Boltzmann constant (Hartree/K) of tblite.
pub const BOLTZMANN_HARTREE_PER_K: f64 = 3.166_808_578_545_117e-6;
/// Electronic temperature of the Fermi smearing (K).
pub const ELECTRONIC_TEMPERATURE_K: f64 = 300.0;

/// Shell scaling of H0 for s, p, d (`kshell`).
pub const K_SHELL: [f64; 3] = [1.85, 2.25, 2.0];
/// Scaling of s-p pairs.
pub const K_SP: f64 = 2.08;
/// Scaling with a non-valence (diffuse) shell.
pub const K_DIFF: f64 = 2.85;
/// Prefactor of the squared electronegativity difference (`0.005 (enshell_i + enshell_j)`).
pub const K_EN: f64 = -0.007;
/// CN dependence of the self energies of s, p, d shells (times 0.01), for xtb's element kinds
/// 1 (the main group) and 2 (Sc to Cr); kind 0 has none (`cnshell` of `gfn1.f90`).
pub const K_CN: [[f64; 3]; 2] = [[0.6, -0.3, -0.5], [0.6, -0.3, 0.5]];
/// Pair scaling of Ni-H.
pub const K_PAIR_NIH: f64 = 0.90;
/// Pair scaling of Re-H and Pt-H.
pub const K_PAIR_REH_PTH: f64 = 0.80;
/// Pair scaling of two d-block metals by their rows (3d, 4d, 5d), averaged over the two
/// (`setGFN1PairParam` of `gfn1.f90`).
pub const K_PAIR_D_ROWS: [f64; 3] = [1.1, 1.2, 1.2];
/// Pair scaling of H-H.
pub const K_PAIR_HH: f64 = 0.96;
/// Pair scaling of N-H.
pub const K_PAIR_NH: f64 = 1.04;
/// Pair scaling of B-H.
pub const K_PAIR_BH: f64 = 0.95;
/// Pair scaling of B-P.
pub const K_PAIR_BP: f64 = 0.97;
/// Pair scaling of N-Si.
pub const K_PAIR_NSI: f64 = 1.01;
/// Halogen-bond damping.
pub const XB_DAMP: f64 = 0.44;
/// Halogen-bond radius scaling.
pub const XB_RAD: f64 = 1.3;
/// Exponent of the repulsion on the distance.
pub const REP_KEXP: f64 = 1.5;
/// D3(BJ): s6, s8, a1, a2 (Bohr); no three-body term.
pub const D3_S6: f64 = 1.0;
/// D3(BJ) s8.
pub const D3_S8: f64 = 2.4;
/// D3(BJ) a1.
pub const D3_A1: f64 = 0.63;
/// D3(BJ) a2 (Bohr).
pub const D3_A2: f64 = 5.0;
/// Cutoff of the dispersion pairs (Bohr, tblite).
pub const D3_CUTOFF: f64 = 50.0;
/// Cutoff of the coordination numbers (Bohr, tblite; for H0 and for D3).
pub const CN_CUTOFF: f64 = 25.0;
/// Squared distance (Bohr^2) within which a halogen-bond acceptor counts.
pub const XB_CUTOFF2: f64 = 400.0;

/// One shell of an element.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Gfn1Shell {
    /// Angular momentum.
    pub l: usize,
    /// Principal quantum number.
    pub n: u8,
    /// Slater exponent.
    pub zeta: f64,
    /// Primitives of the STO-nG expansion.
    pub nprim: usize,
    /// Valence shell (the hydrogen 2s shell is not one).
    pub valence: bool,
    /// Self energy (eV).
    pub self_energy_ev: f64,
    /// Shell polynomial coefficient (times 0.01 in the formula).
    pub kpoly: f64,
    /// Relative hardness of the shell (`eta (1 + kappa)`).
    pub kappa: f64,
    /// Reference occupation.
    pub ref_occ: f64,
}

/// One element.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Gfn1Element {
    /// Atomic number.
    pub z: u8,
    /// Shells.
    pub shells: &'static [Gfn1Shell],
    /// Chemical hardness (Hartree).
    pub eta: f64,
    /// Third-order hardness derivative (Hartree).
    pub gamma3: f64,
    /// Repulsion exponent (Bohr^-3/2).
    pub rep_alpha: f64,
    /// Effective nuclear charge of the repulsion.
    pub rep_zeff: f64,
    /// Halogen-bond strength (Hartree).
    pub xb_strength: f64,
    /// Pauling electronegativity.
    pub en: f64,
    /// Atomic radius (Angstrom; the distance polynomial and the halogen bond).
    pub atomic_rad: f64,
    /// D3 covalent radius (Angstrom, before the factor 4/3).
    pub cov_rad_d3: f64,
    /// How the self energies shift with the coordination number: xtb's `gfn1Kinds`, 1 for the
    /// main group (not Li, Be, B, Na, Mg, Al, K, Ca, Ga), 2 for Sc to Cr, 0 for none.
    pub cn_kind: u8,
}

impl Gfn1Element {
    /// The factor (times the self energy and 0.01) of the shift of a shell of angular
    /// momentum `l` with the coordination number.
    pub fn cn_factor(&self, l: usize) -> f64 {
        match self.cn_kind {
            1 | 2 => K_CN[usize::from(self.cn_kind) - 1][l.min(2)],
            _ => 0.0,
        }
    }

    /// Valence electrons (the sum of the reference occupations).
    pub fn valence_electrons(&self) -> f64 {
        self.shells.iter().map(|s| s.ref_occ).sum()
    }
}

/// A shell of the element table.
#[allow(clippy::too_many_arguments)]
pub(super) const fn sh(
    l: usize,
    n: u8,
    zeta: f64,
    nprim: usize,
    valence: bool,
    self_energy_ev: f64,
    kpoly: f64,
    kappa: f64,
    ref_occ: f64,
) -> Gfn1Shell {
    Gfn1Shell {
        l,
        n,
        zeta,
        nprim,
        valence,
        self_energy_ev,
        kpoly,
        kappa,
        ref_occ,
    }
}

/// Halogens of the halogen-bond correction (Cl, Br, I, At; `xbond` of xtb's
/// `scf_module.F90`).
pub const XB_HALOGENS: [u8; 4] = [17, 35, 53, 85];
/// Acceptors of the halogen-bond correction (N, O, P, S).
pub const XB_ACCEPTORS: [u8; 4] = [7, 8, 15, 16];

/// The elements GFN1-xTB has parameters for, as error messages name them.
pub const ELEMENT_RANGE: &str = "H to Rn (Z = 1 to 86)";

/// The parameters of `element`, or an error for the elements GFN1-xTB has no parameters for.
pub fn element(element: Element) -> MoptResult<&'static Gfn1Element> {
    let z = element.atomic_number();
    ELEMENTS
        .iter()
        .find(|e| u32::from(e.z) == u32::from(z))
        .ok_or_else(|| {
            MoptError::unsupported(format!(
                "GFN1-xTB has parameters for {ELEMENT_RANGE} only, not {} (Z = {z})",
                element.symbol()
            ))
        })
}

/// The pair scaling `kpair` of two elements (`initHamiltonian` and `setGFN1PairParam` of
/// `gfn1.f90`; `tools/params/gen_gfn1_xtb.py` checks this rule against tblite's pair list).
pub fn pair_scaling(za: u8, zb: u8) -> f64 {
    match (za.min(zb), za.max(zb)) {
        (1, 1) => K_PAIR_HH,
        (1, 5) => K_PAIR_BH,
        (1, 7) => K_PAIR_NH,
        (1, 28) => K_PAIR_NIH,
        (1, 75) | (1, 78) => K_PAIR_REH_PTH,
        (5, 15) => K_PAIR_BP,
        (7, 14) => K_PAIR_NSI,
        (a, b) => match (d_block_row(a), d_block_row(b)) {
            (Some(i), Some(j)) => 0.5 * (K_PAIR_D_ROWS[i] + K_PAIR_D_ROWS[j]),
            _ => 1.0,
        },
    }
}

/// The row of a d-block metal of the pair scaling (`dBlockRow` of `gfn1.f90`: Sc to Cu, Y to
/// Ag, La to Au), `None` for the other elements.
fn d_block_row(z: u8) -> Option<usize> {
    match z {
        21..=29 => Some(0),
        39..=47 => Some(1),
        57..=79 => Some(2),
        _ => None,
    }
}

